import {tourConnections} from './tour-connections.js';
export function createPhotoTourMedia(vehicle,photos,node){const wrapper=node('div','vehicle-media-panel');if(!vehicle.torres360?.enabled){wrapper.append(photos);return wrapper;}const tabs=node('div','vehicle-view-tabs'),photo=node('button','','Fotografías'),tour=node('button','','Entrar a Torres 360'),panel=node('div');photo.type=tour.type='button';panel.hidden=true;photo.setAttribute('aria-pressed','true');tour.setAttribute('aria-pressed','false');tabs.append(photo,tour);wrapper.append(tabs,photos,panel);let mounted=false;photo.onclick=()=>{photos.hidden=false;panel.hidden=true;photo.setAttribute('aria-pressed','true');tour.setAttribute('aria-pressed','false');};tour.onclick=()=>{photos.hidden=true;panel.hidden=false;photo.setAttribute('aria-pressed','false');tour.setAttribute('aria-pressed','true');if(!mounted){mounted=true;panel.append(createTorresTour(vehicle.torres360,node));}};return wrapper;}
export function createTorresTour(tour,node){
 const host=node('section','torres-tour'),head=node('header','tour-heading'),brand=node('div');brand.append(node('span','eyebrow','ENTRA. EXPLORA. RECUÉRDALO.'),node('h3','','Torres 360'));const logo=node('img');logo.src='/assets/logo.png';logo.alt='Torres Garage';head.append(brand,logo);const stage=node('div','tour-stage'),nav=node('nav','tour-nav'),tools=node('div','tour-controls'),hint=node('p','tour-hint'),notice=node('p','tour-notice');nav.setAttribute('aria-label','Escenas de Torres 360');host.append(head,stage,tools,hint,nav,notice);
 const views=[...(tour.exterior?.length?[{label:'Exterior · giro 360°',kind:'sequence',frames:tour.exterior}]:[]),...(tour.scenes||[])];let selected=0,frame=0,zoom=1,dispose=()=>{},revision=0,image=null,drag=null;const buttons=[];
 const button=(text,fn)=>{const b=node('button','',text);b.type='button';b.onclick=fn;return b;};const prev=button('Vista anterior',()=>choose((selected-1+views.length)%views.length)),next=button('Vista siguiente',()=>choose((selected+1)%views.length)),closer=button('Acercar +',()=>{zoom=Math.min(2,zoom+.15);if(image)image.style.transform=`scale(${zoom})`;host.dispatchEvent(new CustomEvent('tour-zoom',{detail:zoom}));}),farther=button('Alejar −',()=>{zoom=Math.max(.7,zoom-.15);if(image)image.style.transform=`scale(${zoom})`;host.dispatchEvent(new CustomEvent('tour-zoom',{detail:zoom}));}),full=button('Ampliar experiencia',()=>{host.classList.add('tour-expanded');close.hidden=false;close.focus();}),close=button('Cerrar vista ampliada',()=>{host.classList.remove('tour-expanded');close.hidden=true;full.focus();});close.hidden=true;head.append(close);host.addEventListener('keydown',e=>{if(e.key==='Escape'&&host.classList.contains('tour-expanded')){e.preventDefault();e.stopPropagation();close.click();}});tools.append(prev,next,closer,farther,full);
 views.forEach((v,i)=>{const b=button(v.label,()=>choose(i)),thumb=node('img');thumb.src=v.photo||v.frames?.[0];thumb.alt='';thumb.loading='lazy';b.prepend(thumb);buttons.push(b);nav.append(b);});
 const drawFrame=view=>{image.src=view.frames[(frame+view.frames.length)%view.frames.length];for(const delta of [-1,1]){const prefetch=new Image();prefetch.src=view.frames[(frame+delta+view.frames.length)%view.frames.length];}hint.textContent=`Arrastra para rodear el vehículo · Toma ${(frame+view.frames.length)%view.frames.length+1} de ${view.frames.length}`;};
 async function choose(index){const version=++revision;dispose();dispose=()=>{};selected=index;frame=0;zoom=1;image=null;stage.replaceChildren();drag=null;buttons.forEach((b,i)=>b.setAttribute('aria-pressed',String(i===index)));const view=views[index];if(!view){hint.textContent='Torres 360 está en preparación.';return;}notice.textContent=tour.photographicDemo?'DEMO FOTOGRÁFICA · Interior real de un BMW. Exterior pendiente: no se han mezclado unidades. Fotografía: Miguel Angel Victoria / Sinaloa 360 · CC BY 4.0.':tour.demo?'DEMO ILUSTRADA: exterior e interiores ficticios para probar el recorrido. No son fotografías de una unidad real.':view.photo==='/assets/examples/torres360-demo.svg'?'DEMO DE FUNCIONAMIENTO: estudio ilustrado, no es el interior real de este auto. Carga tus propias panorámicas para recorrer la unidad real.':'';
 stage.classList.toggle('is-panorama',view.kind==='panorama');if(view.kind==='panorama'){hint.textContent='Arrastra para mirar alrededor · Usa + y − para el zoom';const loading=node('span','tour-loading','Cargando panorama…');stage.append(loading);try{const {mountPanorama}=await import('./torres-panorama-immersive.js');if(version!==revision||!host.isConnected)return;dispose=await mountPanorama(stage,view.photo,host,{points:tourConnections(views,index),navigate:choose,yaw:view.yaw,pitch:view.pitch});if(version!==revision){dispose();return;}loading.remove();reveal();}catch{loading.textContent='No se pudo abrir este panorama. Elige otra vista.';}return;}
 image=node('img','tour-image');image.alt=view.label;image.draggable=false;image.onerror=()=>{hint.textContent='No se pudo cargar esta fotografía.';};stage.append(image);if(view.kind==='sequence')drawFrame(view);else{image.src=view.photo;hint.textContent='Fotografía de detalle · Usa las vistas para seguir explorando';}addLinks(index);reveal();
 }
 function reveal(){if(!matchMedia('(prefers-reduced-motion: reduce)').matches)stage.animate([{opacity:.25,transform:'scale(1.025)'},{opacity:1,transform:'scale(1)'}],{duration:400,easing:'ease-out'});}
 function addLinks(index){if(views.length<2)return;const links=node('div','tour-scene-links');for(const point of tourConnections(views,index)){const b=button('Punto: '+point.label,()=>choose(point.target));b.className='tour-point';b.style.left=point.x+'%';b.style.top=point.y+'%';b.setAttribute('aria-label','Ir a '+point.label);links.append(b);}stage.append(links);}
 stage.addEventListener('pointerdown',e=>{if(e.target.closest('button')||views[selected]?.kind!=='sequence')return;drag={id:e.pointerId,x:e.clientX};stage.setPointerCapture(e.pointerId);});stage.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId)return;const dx=e.clientX-drag.x;if(Math.abs(dx)>9){frame=(frame-Math.trunc(dx/9)+views[selected].frames.length*1000)%views[selected].frames.length;drag.x=e.clientX;drawFrame(views[selected]);}});const end=()=>drag=null;stage.addEventListener('pointerup',end);stage.addEventListener('pointercancel',end);
 stage.tabIndex=0;stage.setAttribute('aria-label','Explorador Torres 360. Flechas para cambiar de vista o girar el exterior.');stage.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();const step=e.key==='ArrowLeft'?-1:1;if(views[selected]?.kind==='panorama'){host.dispatchEvent(new CustomEvent('tour-look',{detail:step*.12}));}else if(views[selected]?.kind==='sequence'){frame=(frame+step+views[selected].frames.length)%views[selected].frames.length;drawFrame(views[selected]);}else choose((selected+step+views.length)%views.length);});
 const observer=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting)){observer.disconnect();choose(0);}});observer.observe(host);return host;
}
